contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(amount > 0);
        require(address(this).balance >= amount);

        c.sendMoney(address(c), amount); if (__ESBMC_reverted()) return;

        address owner = c.owner(); if (__ESBMC_reverted()) return;
        require(owner == address(this));

        uint beforeOwner = address(this).balance;
        uint beforeContract = address(c).balance;

        bool reverted;
        c.withdrawAll(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        assert(
            (reverted && address(c).balance == beforeContract) ||
            (!reverted && address(c).balance == 0 && address(this).balance == beforeOwner + beforeContract)
        );
    }

    receive() external payable {}
}

